import { Component, OnInit, ViewChild, ElementRef, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Chart, registerables } from 'chart.js';
import { AnalyticsService } from '../../services/analytics.service';
import { AnalyticsOverview, DepartmentStatistics, SkillDemand, AnalyticsFilters } from '../../models/analytics.model';
import { firstValueFrom } from 'rxjs';

Chart.register(...registerables);

@Component({
  selector: 'app-advanced-analytics',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './advanced-analytics.component.html',
  styleUrls: ['./advanced-analytics.component.css']
})
export class AdvancedAnalyticsComponent implements OnInit, OnDestroy {
  @ViewChild('departmentChart') departmentChartRef!: ElementRef<HTMLCanvasElement>;
  @ViewChild('skillsChart') skillsChartRef!: ElementRef<HTMLCanvasElement>;

  analyticsOverview: AnalyticsOverview | null = null;
  departmentStats: DepartmentStatistics[] = [];
  skillsDemand: SkillDemand[] = [];

  departmentChart: Chart | null = null;
  skillsChart: Chart | null = null;

  filters: AnalyticsFilters = {};
  activeTab: 'overview' | 'departments' | 'skills' = 'overview';
  loading: boolean = true;
  errorMessage: string | null = null;

  constructor(private analyticsService: AnalyticsService) {}

  ngOnInit(): void {
    this.loadAnalyticsData();
  }

  async loadAnalyticsData(): Promise<void> {
    this.loading = true;
    this.errorMessage = null;

    try {
      const [overview, departments, skills] = await Promise.all([
        firstValueFrom(this.analyticsService.getAnalyticsOverview(this.filters)),
        firstValueFrom(this.analyticsService.getDepartmentStatistics(this.filters)),
        firstValueFrom(this.analyticsService.getSkillsDemandAnalysis(this.filters))
      ]);

      this.analyticsOverview = overview || null;
      this.departmentStats = departments || [];
      this.skillsDemand = skills || [];

      // Met à jour les charts existants au lieu de les recréer
      this.updateDepartmentChart();
      this.updateSkillsChart();

    } catch (err) {
      console.error('Error loading analytics:', err);
      this.errorMessage = 'Erreur lors du chargement des analytics.';
    } finally {
      this.loading = false;
    }
  }

  setActiveTab(tab: 'overview' | 'departments' | 'skills'): void {
    this.activeTab = tab;
  }

  applyFilters(): void {
    this.loadAnalyticsData();
  }

  clearFilters(): void {
    this.filters = {};
    this.loadAnalyticsData();
  }

  private updateDepartmentChart(): void {
    if (!this.departmentChartRef) return;
    const ctx = this.departmentChartRef.nativeElement.getContext('2d');
    if (!ctx) return;

    if (!this.departmentChart) {
      this.departmentChart = new Chart(ctx, {
        type: 'bar',
        data: {
          labels: this.departmentStats.map(d => d.department),
          datasets: [
            { label: 'Candidatures totales', data: this.departmentStats.map(d => d.total_applications), backgroundColor: '#3B82F6' },
            { label: 'Candidatures réussies', data: this.departmentStats.map(d => d.successful_applications), backgroundColor: '#10B981' }
          ]
        },
        options: { responsive: true, maintainAspectRatio: false, scales: { y: { beginAtZero: true } } }
      });
    } else {
      this.departmentChart.data.labels = this.departmentStats.map(d => d.department);
      this.departmentChart.data.datasets[0].data = this.departmentStats.map(d => d.total_applications);
      this.departmentChart.data.datasets[1].data = this.departmentStats.map(d => d.successful_applications);
      this.departmentChart.update();
    }
  }

  private updateSkillsChart(): void {
    if (!this.skillsChartRef) return;
    const ctx = this.skillsChartRef.nativeElement.getContext('2d');
    if (!ctx) return;

    const topSkills = this.skillsDemand.slice(0, 10);

    if (!this.skillsChart) {
      this.skillsChart = new Chart(ctx, {
        type: 'bar',
        data: {
          labels: topSkills.map(s => s.skill_name),
          datasets: [{ label: 'Demande', data: topSkills.map(s => s.demand_count), backgroundColor: '#8B5CF6' }]
        },
        options: { responsive: true, maintainAspectRatio: false, indexAxis: 'y', scales: { x: { beginAtZero: true } } }
      });
    } else {
      this.skillsChart.data.labels = topSkills.map(s => s.skill_name);
      this.skillsChart.data.datasets[0].data = topSkills.map(s => s.demand_count);
      this.skillsChart.update();
    }
  }

  ngOnDestroy(): void {
    this.departmentChart?.destroy();
    this.skillsChart?.destroy();
  }
}
